$dns=fn($h)=>['93.184.216.34'];$token=str_repeat('a',64);
$plan=['revision'=>'0:1','sources'=>[['key'=>'one','url'=>'https://one.example/live/HOST_USER/HOST_PASS/100.m3u8','position'=>0],['key'=>'two','url'=>'https://two.example/live/SECOND_USER/SECOND_PASS/200.m3u8','position'=>1]]];
