$r=sources_relay_resource($s,$token,0,$key,$segment,$dns);relay_check($r['status']===200&&strlen($r['body'])===188,'media fetched server side');
$partial=sources_relay_range($r,'bytes=10-19');relay_check($partial['status']===206&&strlen($partial['body'])===10&&$partial['content_range']==='bytes 10-19/188','byte range supported');
relay_check(sources_relay_range($r,'bytes=500-')['status']===416,'invalid range rejected');
relay_check(sources_relay_range($r,'bytes=0-1,4-5')['status']===416,'multi-range rejected');
$failure=fn($t,$n)=>['status'=>503,'ok'=>false,'headers'=>[],'body'=>'provider error with HOST_PASS'];
$r=sources_relay_resource($s,$token,0,$key,$failure,$dns);relay_check($r['status']===502&&$s['state']['index']===1&&$s['state']['generation']===1,'segment failure advances to next origin');
relay_check($s['resources']===[],'all old-origin resources discarded');
relay_check(!str_contains($r['body'],'HOST_PASS'),'upstream error not exposed');
$r=sources_relay_resource($s,$token,0,$key,$segment,$dns);relay_check($r['status']===409,'old generation cannot serve new-origin segment');
$r=sources_relay_resource($s,$token,1,'root',$transport,$dns);relay_check($r['status']===503,'reopening observes cooldown');
$s['state']['retry_at']=time()-1;$r=sources_relay_resource($s,$token,1,'root',$transport,$dns);relay_check($r['status']===200&&$s['state']['status']==='playing','new origin opens clean manifest');
$seen=[];$redirect=function($t,$n)use(&$seen){$seen[]=$t['host'];return count($seen)===1?['status'=>302,'ok'=>true,'headers'=>['location'=>'https://cdn.example/playlist.m3u8'],'body'=>'']:['status'=>200,'ok'=>true,'headers'=>[],'body'=>'#EXTM3U'];};
sources_relay_fetch('https://public.example/start',1024,$redirect,$dns);relay_check($seen===['public.example','cdn.example'],'each redirect host revalidated and DNS pin supplied');
relay_reject(fn()=>sources_relay_fetch('https://public.example/start',1024,fn($t,$n)=>['status'=>302,'ok'=>true,'headers'=>['location'=>'http://169.254.169.254/metadata'],'body'=>''],$dns),'redirect SSRF refused');
relay_reject(fn()=>sources_relay_fetch('https://public.example/start',2,fn($t,$n)=>['status'=>200,'ok'=>true,'headers'=>[],'body'=>'oversized'],$dns),'bounded response enforced');
relay_check(sources_relative_url('https://host.example/a/b/list.m3u8','../seg.ts?x=1')==='https://host.example/a/seg.ts?x=1','relative URI resolution');
relay_check(sources_relative_url('https://host.example/a/list.m3u8','?token=x')==='https://host.example/a/list.m3u8?token=x','query-only URI resolution');
relay_reject(function()use($token,&$s){sources_relay_manifest('#EXTM3U'."\n".'#EXT-X-KEY:METHOD=AES-128,URI="file:///etc/passwd"','https://host.example/x',$token,$s);},'non-web key rejected');
