try{
 sources_relay_session($token,function(&$state){$state=['expires'=>time()+60,'client_id'=>1,'stream_id'=>10,'value'=>1];},true);
 relay_check(sources_relay_session($token,fn(&$state)=>$state['value'])===1,'private session persists');
